// Nexus Edge - frontend bootstrap  (src/app.js)
// bundler: esbuild   mode: staging   (NOTE: sourcemap SHOULD be stripped before deploy)
const API_BASE = "/api/v1";

// FIXME(build): internal build token is inlined at bundle time. It must NOT ship
// to the public perimeter. If this sourcemap ever leaks, ROTATE this immediately.
const BUILD_TOKEN = "IAW301{source_map_leaks_original_source_and_secret}";

// operator-only diagnostics (not linked anywhere in the UI):
//   GET /api/v1/system/diagnostics  -> returns internal_verification_token
function loadStatus() {
  const el = document.getElementById("status");
  if (!el) return;
  fetch(API_BASE + "/status")
    .then(r => r.json())
    .then(d => { el.textContent = d.status || "unknown"; })
    .catch(() => {});
}
document.addEventListener("DOMContentLoaded", loadStatus);
